const items = $input.all().map((item) => item.json);

// Partition the merged streams by row shape.
const messages = items.filter((r) => r.message_id && !r.last_message_at);
const conversations = items.filter((r) => r.last_message_at);
const events = items.filter((r) => r.event_id);
const appointments = items.filter((r) => r.appointment_id);

const byKey = new Map();
for (const row of messages) {
  const key = String(row.conversation_key || row.parent_phone || 'unknown');
  if (!byKey.has(key)) byKey.set(key, []);
  byKey.get(key).push(row);
}

const convMap = new Map();
for (const c of conversations) convMap.set(String(c.conversation_key), c);

const threads = [];
const seen = new Set();
for (const [key, conv] of convMap) {
  seen.add(key);
  const msgs = (byKey.get(key) || []).sort((a, b) => new Date(a.occurred_at).getTime() - new Date(b.occurred_at).getTime());
  threads.push({
    id: key,
    parent: { id: key, name: conv.parent_name || conv.parent_phone || 'Unknown parent', phone: conv.parent_phone || key, relation: conv.parent_relation || 'Parent' },
    students: conv.student_name ? [{ id: conv.student_name, name: conv.student_name, homeroom: conv.homeroom || '', cohort: '' }] : [],
    status: conv.status || 'open',
    routeTo: conv.route_to || undefined,
    unread: Number(conv.unread || 0),
    messages: msgs.map((m) => ({ id: String(m.message_id || m.id), direction: m.direction, author: m.author, body: m.body || '', at: m.occurred_at })),
    lastActivityAt: msgs.at(-1)?.occurred_at || conv.last_message_at || new Date(0).toISOString(),
  });
}
// Legacy threads that only exist in the append-only message history.
for (const [key, msgsRaw] of byKey) {
  if (seen.has(key)) continue;
  const sorted = msgsRaw.sort((a, b) => new Date(a.occurred_at).getTime() - new Date(b.occurred_at).getTime());
  const last = sorted.at(-1);
  let status = 'open';
  if (last && last.status === 'closed') status = 'closed';
  if (last && last.status === 'routed') status = 'routed';
  const unreadCount = sorted.filter((m) => m.status === 'unread' && m.direction === 'inbound').reduce((n, m) => n + Number(m.unread || 1), 0);
  threads.push({
    id: key,
    parent: { id: key, name: last?.parent_name || last?.parent_phone || 'Unknown parent', phone: last?.parent_phone || key, relation: last?.parent_relation || 'Parent' },
    students: last?.student_name ? [{ id: last.student_name, name: last.student_name, homeroom: last.homeroom || '', cohort: '' }] : [],
    status,
    routeTo: last?.route_to || undefined,
    unread: unreadCount,
    messages: sorted.map((m) => ({ id: String(m.message_id || m.id), direction: m.direction, author: m.author, body: m.body || '', at: m.occurred_at })),
    lastActivityAt: last?.occurred_at,
  });
}
threads.sort((a, b) => new Date(b.lastActivityAt).getTime() - new Date(a.lastActivityAt).getTime());

const evts = events.map((e) => ({
  eventId: e.event_id,
  conversationKey: e.conversation_key || '',
  type: e.type || 'request',
  title: e.title || '',
  body: e.body || '',
  status: e.status || 'queued',
  assignee: e.assignee || '',
  createdAt: e.created_at,
  updatedAt: e.updated_at,
  resolvedAt: e.resolved_at || null,
})).sort((a, b) => new Date(b.createdAt || 0).getTime() - new Date(a.createdAt || 0).getTime());

const appts = appointments.map((a) => ({
  appointmentId: a.appointment_id,
  conversationKey: a.conversation_key || '',
  parentName: a.parent_name || '',
  studentName: a.student_name || '',
  requestedSlot: a.requested_slot || '',
  reason: a.reason || '',
  status: a.status || 'proposed',
  notes: a.notes || '',
  createdAt: a.created_at,
  updatedAt: a.updated_at,
})).sort((a, b) => new Date(b.createdAt || 0).getTime() - new Date(a.createdAt || 0).getTime());

const today = new Date();
today.setHours(0, 0, 0, 0);
const inboundToday = messages.filter((r) => r.direction === 'inbound' && new Date(r.occurred_at).getTime() >= today.getTime()).length;
const repliedToday = messages.filter((r) => r.direction === 'outbound' && new Date(r.occurred_at).getTime() >= today.getTime()).length;
const weekly = [];
for (let offset = 6; offset >= 0; offset -= 1) {
  const day = new Date(today);
  day.setDate(day.getDate() - offset);
  const date = day.toISOString().slice(0, 10);
  const dayRows = messages.filter((r) => String(r.occurred_at).slice(0, 10) === date);
  weekly.push({ day: day.toLocaleDateString('en-GB', { weekday: 'short' }), date, inbound: dayRows.filter((r) => r.direction === 'inbound').length, outbound: dayRows.filter((r) => r.direction === 'outbound').length });
}
const unanswered = threads.filter((t) => t.status !== 'closed' && t.messages.at(-1)?.direction === 'inbound');
const oldest = unanswered.length ? Math.max(0, Math.round((Date.now() - new Date(unanswered.map((t) => t.messages.at(-1).at).sort()[0]).getTime()) / 60000)) : null;
const stats = {
  metrics: {
    inboundToday,
    repliedToday,
    responseRatePct: inboundToday ? Math.round((repliedToday / inboundToday) * 100) : 0,
    avgFirstResponseMin: 0,
    openThreads: threads.filter((t) => t.status !== 'closed').length,
    busiestHour: '',
    slaOldestMinutes: oldest,
    eventsWaiting: events.filter((e) => ['queued', 'processing', 'awaiting_staff'].includes(e.status || 'queued')).length,
    appointmentsPending: appointments.filter((a) => (a.status || 'proposed') === 'proposed').length,
  },
  weekly,
};
return [{ json: { threads, events: evts, appointments: appts, stats } }];

const body = $json.body || {};
const raw = String(body.number || body.conversationKey || '').replace(/\D/g, '');
if (!raw) throw new Error('Missing or invalid number. Send {"number":"911234567890"}');
return [{ json: { waId: raw } }];

const rows = $input.all().flatMap((i) => {
  const r = i.json;
  // dataTable get returns { json: {...} } items; unpack both shapes
  return [r.json && typeof r.json === 'object' ? r.json : r];
});
return [{ json: { ok: true, action: 'list_appointments', appointments: rows } }];
